        for (int c = 0; c < 9; ++c) {
            char ch = b[r][c];
            if (ch == '.') continue;
            int box_idx = (r / 3) * 3 + (c / 3);
            if (rows[r].count(ch) || cols[c].count(ch) || boxes[box_idx].count(ch)) {
                cout << "false" << endl; return 0;
            }
            rows[r].insert(ch); cols[c].insert(ch); boxes[box_idx].insert(ch);
        }
    }
    cout << "true" << endl;
