  if (parts.length < 2) return 0;
  const n = parseInt(parts[0], 10), k = parseInt(parts[1], 10);
  const nums = parts.slice(2, 2 + n).map(Number);
  const counts = new Map([[0, 1]]);
  let curr = 0, ans = 0;
  for (const x of nums) {
    curr += x;
    ans += counts.get(curr - k) || 0;
    counts.set(curr, (counts.get(curr) || 0) + 1);
  }
  return ans;
}

