        int right = n - 1; 
        long maxWater = 0; 

        while (left < right) { 
            long width = right - left; 
            long minHeight = Math.min(height[left], height[right]); 
            long water = width * minHeight; 

            maxWater = Math.max(maxWater, water); 

            if (height[left] < height[right]) { 
                left++; 
            } else { 
                right--; 
            } 
        } 

        System.out.println(maxWater); 
        sc.close(); 
    } 
}

