def solve(input_data):
    parts = input_data.strip().split()
    if not parts: return "0"
    n = int(parts[0])
    nums = [int(x) for x in parts[1:1+n]]
    if n == 0: return "0"
    k = 1
    for i in range(1, n):
        if nums[i] != nums[k - 1]:
            nums[k] = nums[i]
            k += 1
    return f"{k}\n" + " ".join(str(nums[i]) for i in range(k))

