    i = 1
    while q and i < len(vals):
        curr = q.popleft()
        if i < len(vals) and vals[i] != -1:
            curr.left = Node(vals[i]); q.append(curr.left)
        i += 1
        if i < len(vals) and vals[i] != -1:
            curr.right = Node(vals[i]); q.append(curr.right)
        i += 1
    levels = []
    q = deque([root])
    while q:
        sz = len(q)
        lvl = []
        for _ in range(sz):
            node = q.popleft()
            lvl.append(str(node.v))
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        levels.append(" ".join(lvl))
    return "\n".join(levels)

