            if (i < values.length) { 
                if (values[i] != -1) { 
                    current.right = new Node(values[i]); 
                    queue.offer(current.right); 
                } 
                i++; 
            } 
        } 

        return root; 
    } 

    static int countGoodNodes(Node root) { 
        int count = 0; 
        Queue<Node> nodes = new LinkedList<>(); 
        Queue<Integer> maxValues = new LinkedList<>(); 

        nodes.offer(root); 
        maxValues.offer(root.val); 


        while (!nodes.isEmpty()) { 
            Node current = nodes.poll(); 
            int maxSoFar = maxValues.poll(); 

            if (current.val >= maxSoFar) { 
                count++; 
            } 

            int nextMax = Math.max(maxSoFar, current.val); 

            if (current.left != null) { 
                nodes.offer(current.left); 
                maxValues.offer(nextMax); 
            } 

            if (current.right != null) { 
                nodes.offer(current.right); 
                maxValues.offer(nextMax); 
            } 
        } 

        return count; 
    } 

}

