        for (int i = 0; i < n; i++) { 
            values[i] = sc.nextInt(); 
        } 

        Node root = buildTree(values); 

        maxSum = Long.MIN_VALUE; 
        maxPathSum(root); 

        System.out.println(maxSum); 

        sc.close(); 
    } 

    static Node buildTree(int[] values) { 
        if (values.length == 0) { 
            return null; 
        } 


        Node root = new Node(values[0]); 
        Queue<Node> queue = new LinkedList<>(); 
        queue.offer(root); 

        int i = 1; 

        while (!queue.isEmpty() && i < values.length) { 
            Node current = queue.poll(); 

            if (i < values.length) { 
                if (values[i] != -1) { 
                    current.left = new Node(values[i]); 
                    queue.offer(current.left); 
                } 
                i++; 
            } 

            if (i < values.length) { 
                if (values[i] != -1) { 
                    current.right = new Node(values[i]); 
                    queue.offer(current.right); 
                } 
                i++; 
            } 

        } 

        return root; 
    } 

    static long maxPathSum(Node root) { 
        if (root == null) { 
            return 0; 
        } 

        long leftGain = Math.max(0, maxPathSum(root.left)); 
        long rightGain = Math.max(0, maxPathSum(root.right)); 

        long currentPathSum = root.val + leftGain + rightGain; 
        maxSum = Math.max(maxSum, currentPathSum); 

        return root.val + Math.max(leftGain, rightGain); 
    } 
}

