import java.io.*; 
import java.util.*; 

public class Solution { 

    static class Node { 
        int val; 
        Node left, right; 

        Node(int val) { 
            this.val = val; 
        } 
    } 

    static Node buildTree(String[] values) { 
        if (values.length == 0 || values[0].equals("-1")) { 
            return null; 
        } 

        Node root = new Node(Integer.parseInt(values[0])); 
        Queue<Node> queue = new LinkedList<>(); 
        queue.offer(root); 


        int i = 1; 

        while (!queue.isEmpty() && i < values.length) { 
            Node current = queue.poll(); 

            if (i < values.length) { 
                int leftVal = Integer.parseInt(values[i++]); 
                if (leftVal != -1) { 
                    current.left = new Node(leftVal); 
                    queue.offer(current.left); 
                } 
            } 

            if (i < values.length) { 
                int rightVal = Integer.parseInt(values[i++]); 
                if (rightVal != -1) { 
                    current.right = new Node(rightVal); 
                    queue.offer(current.right); 
                } 
            } 
        } 

        return root; 
    } 


    static void findPaths(Node node, long target, long sum, 
                          List<Integer> path, 
                          List<List<Integer>> result) { 
        if (node == null) return; 

        path.add(node.val); 
        sum += node.val; 

        if (node.left == null && node.right == null && sum == target) { 
            result.add(new ArrayList<>(path)); 
        } else { 
            findPaths(node.left, target, sum, path, result); 
            findPaths(node.right, target, sum, path, result); 
        } 

        path.remove(path.size() - 1); 
    } 

    static String formatResult(List<List<Integer>> result) { 
        StringBuilder sb = new StringBuilder("["); 
        for (int i = 0; i < result.size(); i++) { 
            if (i > 0) sb.append(","); 
            sb.append("["); 

            for (int j = 0; j < result.get(i).size(); j++) { 
                if (j > 0) sb.append(","); 
                sb.append(result.get(i).get(j)); 
            } 
            sb.append("]"); 
        } 
        sb.append("]"); 
        return sb.toString(); 
    } 

    public static void main(String[] args) throws Exception { 
        BufferedReader br = new BufferedReader( 
                new InputStreamReader(System.in)); 

        List<String> lines = new ArrayList<>(); 
        String line; 
        while ((line = br.readLine()) != null) { 
            if (!line.trim().isEmpty()) lines.add(line.trim()); 
        } 

        if (lines.isEmpty()) { 
            System.out.println("[]"); 
            return; 
        } 


        String targetLine = lines.get(lines.size() - 1); 
        long target = Long.parseLong(targetLine); 

        StringBuilder treeInput = new StringBuilder(); 
        for (int i = 0; i < lines.size() - 1; i++) { 
            treeInput.append(lines.get(i)).append(" "); 
        } 

        String[] values = treeInput.toString().trim().split("\\s+"); 
        Node root = buildTree(values); 

        List<List<Integer>> result = new ArrayList<>(); 
        findPaths(root, target, 0L, new ArrayList<>(), result); 

        System.out.println(formatResult(result)); 
    } 
}

