import java.io.*; 
import java.util.*; 

public class Solution { 

    static class TreeNode { 
        int val; 
        TreeNode left, right; 

        TreeNode(int val) { 
            this.val = val; 

        } 
    } 

    static void dfs(TreeNode root, TreeMap<Integer, List<int[]>> map, 
                    int col, int row) { 
        if (root == null) { 
            return; 
        } 

        map.putIfAbsent(col, new ArrayList<>()); 
        map.get(col).add(new int[]{row, root.val}); 

        dfs(root.left, map, col - 1, row + 1); 
        dfs(root.right, map, col + 1, row + 1); 
    } 

    static List<List<Integer>> verticalTraversal(TreeNode root) { 
        List<List<Integer>> result = new ArrayList<>(); 
        TreeMap<Integer, List<int[]>> map = new TreeMap<>(); 

        dfs(root, map, 0, 0); 

        for (List<int[]> nodes : map.values()) { 
            nodes.sort((a, b) -> { 

                if (a[0] != b[0]) { 
                    return Integer.compare(a[0], b[0]); 
                } 
                return Integer.compare(a[1], b[1]); 
            }); 

            List<Integer> column = new ArrayList<>(); 
            for (int[] node : nodes) { 
                column.add(node[1]); 
            } 

            result.add(column); 
        } 

        return result; 
    } 

    static TreeNode buildTree(String[] values) { 
        if (values.length == 0 || values[0].equals("-1")) { 
            return null; 
        } 

        TreeNode root = new TreeNode(Integer.parseInt(values[0])); 
        Queue<TreeNode> queue = new LinkedList<>(); 

        queue.offer(root); 

        int i = 1; 

        while (!queue.isEmpty() && i < values.length) { 
            TreeNode current = queue.poll(); 

            int leftValue = Integer.parseInt(values[i++]); 
            if (leftValue != -1) { 
                current.left = new TreeNode(leftValue); 
                queue.offer(current.left); 
            } 

            if (i < values.length) { 
                int rightValue = Integer.parseInt(values[i++]); 
                if (rightValue != -1) { 
                    current.right = new TreeNode(rightValue); 
                    queue.offer(current.right); 
                } 
            } 
        } 

        return root; 
    } 


    static String formatResult(List<List<Integer>> result) { 
        StringBuilder sb = new StringBuilder("["); 
        for (int i = 0; i < result.size(); i++) { 
            if (i > 0) sb.append(","); 
            sb.append("["); 
            for (int j = 0; j < result.get(i).size(); j++) { 
                if (j > 0) sb.append(","); 
                sb.append(result.get(i).get(j)); 
            } 
            sb.append("]"); 
        } 
        return sb.append("]").toString(); 
    } 

    public static void main(String[] args) throws Exception { 
        BufferedReader br = new BufferedReader( 
                new InputStreamReader(System.in)); 

        String firstLine = br.readLine(); 
        if (firstLine == null || firstLine.trim().isEmpty()) { 
            System.out.println("[]"); 
            return; 
        } 


        int n = Integer.parseInt(firstLine.trim()); 

        StringBuilder input = new StringBuilder(); 
        String line; 
        while ((line = br.readLine()) != null) { 
            input.append(line).append(" "); 
        } 

        String data = input.toString().trim(); 

        if (n == 0 || data.isEmpty()) { 
            System.out.println("[]"); 
            return; 
        } 

        String[] values = data.split("\\s+"); 
        TreeNode root = buildTree(values); 

        System.out.println(formatResult(verticalTraversal(root))); 
    } 
}

