import java.io.*; 
import java.util.*; 

public class Solution { 

    static class TrieNode { 
        TrieNode[] children = new TrieNode[26]; 
        boolean isEnd; 
    } 

    static class Trie { 
        private final TrieNode root = new TrieNode(); 

        public void insert(String word) { 
            TrieNode current = root; 

            for (int i = 0; i < word.length(); i++) { 
                int index = word.charAt(i) - 'a'; 

                if (index < 0 || index >= 26) { 
                    return; 
                } 


                if (current.children[index] == null) { 
                    current.children[index] = new TrieNode(); 
                } 

                current = current.children[index]; 
            } 

            current.isEnd = true; 
        } 

        public boolean search(String word) { 
            TrieNode node = findNode(word); 
            return node != null && node.isEnd; 
        } 

        public boolean startsWith(String prefix) { 
            return findNode(prefix) != null; 
        } 

        private TrieNode findNode(String text) { 
            TrieNode current = root; 

            for (int i = 0; i < text.length(); i++) { 
                int index = text.charAt(i) - 'a'; 


                if (index < 0 || index >= 26) { 
                    return null; 
                } 

                if (current.children[index] == null) { 
                    return null; 
                } 

                current = current.children[index]; 
            } 

            return current; 
        } 
    } 

    public static void main(String[] args) throws IOException { 
        BufferedReader br = new BufferedReader( 
                new InputStreamReader(System.in)); 

        String firstLine = br.readLine(); 
        if (firstLine == null || firstLine.trim().isEmpty()) { 
            return; 
        } 


        int operations = Integer.parseInt(firstLine.trim()); 
        Trie trie = new Trie(); 
        StringBuilder output = new StringBuilder(); 

        for (int i = 0; i < operations; i++) { 
            String line = br.readLine(); 
            if (line == null) { 
                break; 
            } 

            line = line.trim(); 
            if (line.isEmpty()) { 
                continue; 
            } 

            String[] parts = line.split("\\s+", 2); 
            String operation = parts[0]; 
            String word = parts.length > 1 ? parts[1].trim() : ""; 

            // Handle a quoted empty string: startsWith "" 
            if (word.equals("\"\"") || word.equals("''")) { 
                word = ""; 
            } 


            switch (operation) { 
                case "insert": 
                    trie.insert(word); 
                    break; 

                case "search": 
                    output.append(trie.search(word)).append('\n'); 
                    break; 

                case "startsWith": 
                    output.append(trie.startsWith(word)).append('\n'); 
                    break; 
            } 
        } 

        System.out.print(output); 
    } 
}

