public class Solution { 

    static class Point { 
        int x, y; 
        long distance; 

        Point(int x, int y) { 
            this.x = x; 
            this.y = y; 
            this.distance = (long) x * x + (long) y * y; 
        } 
    } 


    public static void main(String[] args) throws IOException { 
        BufferedReader br = new BufferedReader( 
                new InputStreamReader(System.in)); 

        int n = Integer.parseInt(br.readLine().trim()); 

        PriorityQueue<Point> maxHeap = new PriorityQueue<>( 
                (a, b) -> Long.compare(b.distance, a.distance)); 

        for (int i = 0; i < n; i++) { 
            String line = br.readLine(); 

            while (line == null || line.trim().isEmpty()) { 
                line = br.readLine(); 
            } 

            StringTokenizer st = new StringTokenizer(line); 
            int x = Integer.parseInt(st.nextToken()); 
            int y = Integer.parseInt(st.nextToken()); 

            maxHeap.offer(new Point(x, y)); 

            if (maxHeap.size() > Integer.MAX_VALUE) { 

                maxHeap.poll(); 
            } 
        } 

        int k = Integer.parseInt(br.readLine().trim()); 

        // Keep only the k closest points. 
        while (maxHeap.size() > k) { 
            maxHeap.poll(); 
        } 

        List<Point> result = new ArrayList<>(maxHeap); 
        result.sort((a, b) -> Long.compare(a.distance, b.distance)); 

        StringBuilder output = new StringBuilder(); 

        for (Point p : result) { 
            if (output.length() > 0) { 
                output.append('\n'); 
            } 
            output.append(p.x).append(' ').append(p.y); 
        } 

        System.out.println(output); 

    } 
}

