                    System.out.println( 
                        twitter.getNewsFeed(Integer.parseInt(parts[1])) 
                    ); 
                    break; 

                case "follow": 
                    twitter.follow( 
                        Integer.parseInt(parts[1]), 
                        Integer.parseInt(parts[2]) 
                    ); 
                    break; 

                case "unfollow": 
                    twitter.unfollow( 
                        Integer.parseInt(parts[1]), 
                        Integer.parseInt(parts[2]) 
                    ); 
                    break; 
            } 

        } 
    } 
}

