            m = re.findall(r'\d+', line)
            u = int(m[0])
            following = follows.get(u, set()) | {u}
            feed = []
            for uid, tid in reversed(tweets):
                if uid in following:
                    feed.append(tid)
                    if len(feed) == 10: break
            res.append(f"[{','.join(map(str, feed))}]")
        elif line.startswith("follow"):
            import re
            m = re.findall(r'\d+', line)
            u1, u2 = int(m[0]), int(m[1])
            if u1 not in follows: follows[u1] = set()
            follows[u1].add(u2)
        elif line.startswith("unfollow"):
            import re
            m = re.findall(r'\d+', line)
            u1, u2 = int(m[0]), int(m[1])
            if u1 in follows and u2 in follows[u1]: follows[u1].remove(u2)
