  if (maxC > Math.floor((s.length + 1) / 2)) return '""';
  const arr = Object.entries(cnt).map(([ch, count]) => ({ ch, count }));
  let res = "", prev = null;
  while (arr.length > 0) {
    arr.sort((a, b) => b.count - a.count);
    let cur = arr.shift();
    res += cur.ch;
    cur.count--;
    if (prev && prev.count > 0) arr.push(prev);
    prev = cur;
  }
  return res;
}

