    if (!(cin >> S) || S.length() < 4 || S.length() > 12) { cout << "[]" << endl; return 0; }
    backtrack(0, 0, "");
    if (res.empty()) cout << "[]" << endl;
    else for (const auto& ip : res) cout << ip << endl;
    return 0;
}

