import java.util.*; 
import java.util.regex.*; 

class Node { 
    public int val; 
    public List<Node> neighbors; 

    public Node() { 
        val = 0; 
        neighbors = new ArrayList<>(); 
    } 

    public Node(int val) { 
        this.val = val; 
        neighbors = new ArrayList<>(); 
    } 
} 

public class Solution { 

    public Node cloneGraph(Node node) { 
        if (node == null) { 

            return null; 
        } 

        Map<Node, Node> mp = new HashMap<>(); 
        Queue<Node> queue = new LinkedList<>(); 

        Node clone = new Node(node.val); 
        mp.put(node, clone); 
        queue.add(node); 

        while (!queue.isEmpty()) { 
            Node curr = queue.poll(); 

            for (Node neighbor : curr.neighbors) { 
                if (!mp.containsKey(neighbor)) { 
                    mp.put(neighbor, new Node(neighbor.val)); 
                    queue.add(neighbor); 
                } 

                mp.get(curr).neighbors.add(mp.get(neighbor)); 
            } 
        } 

        return clone; 

    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        StringBuilder input = new StringBuilder(); 

        while (sc.hasNextLine()) { 
            input.append(sc.nextLine()).append(" "); 
        } 

        Pattern pattern = 
            Pattern.compile("(\\d+)\\s*:\\s*\\[([^\\]]*)\\]"); 
        Matcher matcher = pattern.matcher(input.toString()); 

        Map<Integer, Node> nodes = new LinkedHashMap<>(); 
        Map<Integer, List<Integer>> adjacency = new 
LinkedHashMap<>(); 

        while (matcher.find()) { 
            int val = Integer.parseInt(matcher.group(1)); 
            String values = matcher.group(2).trim(); 
            List<Integer> neighbors = new ArrayList<>(); 

            if (!values.isEmpty()) { 

                for (String value : values.split(",")) { 
                    neighbors.add(Integer.parseInt(value.trim())); 
                } 
            } 

            adjacency.put(val, neighbors); 
            nodes.putIfAbsent(val, new Node(val)); 
        } 

        for (Map.Entry<Integer, List<Integer>> entry : 
adjacency.entrySet()) { 
            Node node = nodes.get(entry.getKey()); 

            for (int neighborVal : entry.getValue()) { 
                nodes.putIfAbsent(neighborVal, new Node(neighborVal)); 
                node.neighbors.add(nodes.get(neighborVal)); 
            } 
        } 

        Node start = nodes.isEmpty() 
            ? null 
            : nodes.values().iterator().next(); 

        Solution solution = new Solution(); 

        Node cloned = solution.cloneGraph(start); 

        if (cloned != null) { 
            Queue<Node> queue = new LinkedList<>(); 
            Set<Node> visited = new HashSet<>(); 

            queue.add(cloned); 
            visited.add(cloned); 

            while (!queue.isEmpty()) { 
                Node curr = queue.poll(); 
                List<Integer> neighborVals = new ArrayList<>(); 

                for (Node neighbor : curr.neighbors) { 
                    neighborVals.add(neighbor.val); 

                    if (visited.add(neighbor)) { 
                        queue.add(neighbor); 
                    } 
                } 

                System.out.println(curr.val + ": " + neighborVals); 
            } 
        } 


        sc.close(); 
    } 
}

