    } 

    public static int rob(int[] nums) { 
        int n = nums.length; 

        if (n == 0) { 
            return 0; 
        } 


        if (n == 1) { 
            return nums[0]; 
        } 

        return Math.max( 
            robLinear(nums, 0, n - 2), 
            robLinear(nums, 1, n - 1) 
        ); 
    } 

    private static int robLinear(int[] nums, int start, int end) { 
        int prev2 = 0; 
        int prev1 = 0; 

        for (int i = start; i <= end; i++) { 
            int current = Math.max(prev1, prev2 + nums[i]); 
            prev2 = prev1; 
            prev1 = current; 
        } 

        return prev1; 
    } 
}

