function solve(input) {
  const parts = input.trim().split(/\s+/);
  if (parts.length < 2) return 0;
  const R = parseInt(parts[0], 10), C = parseInt(parts[1], 10);
  const grid = [];
  let idx = 2;
  for (let r = 0; r < R; r++) { grid.push(parts.slice(idx, idx + C).map(Number)); idx += C; }
  const memo = Array.from({ length: R }, () => Array(C).fill(0));
  function dfs(r, c) {
    if (memo[r][c]) return memo[r][c];
    let res = 1;
    const dr = [-1, 1, 0, 0], dc = [0, 0, -1, 1];
    for (let d = 0; d < 4; d++) {
      const nr = r + dr[d], nc = c + dc[d];
      if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] > grid[r][c]) {
        res = Math.max(res, 1 + dfs(nr, nc));
      }
    }
    return memo[r][c] = res;
  }
  let ans = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) ans = Math.max(ans, dfs(r, c));
  return ans;
}

