    } 

    public static int canCompleteCircuit(int[] gas, int[] cost) { 
        int totalGas = 0; 
        int currentGas = 0; 
        int start = 0; 

        for (int i = 0; i < gas.length; i++) { 
            int difference = gas[i] - cost[i]; 

            totalGas += difference; 
            currentGas += difference; 


            if (currentGas < 0) { 
                start = i + 1; 
                currentGas = 0; 
            } 
        } 

        return totalGas >= 0 ? start : -1; 
    } 
}

