import java.util.*; 

public class Solution { 
    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        int n = sc.nextInt(); 
        int[][] intervals = new int[n][2]; 

        for (int i = 0; i < n; i++) { 
            intervals[i][0] = sc.nextInt(); 

            intervals[i][1] = sc.nextInt(); 
        } 

        int m = sc.nextInt(); 
        int[] queries = new int[m]; 

        for (int i = 0; i < m; i++) { 
            queries[i] = sc.nextInt(); 
        } 

        sc.close(); 

        int[] result = minInterval(intervals, queries); 

        for (int i = 0; i < result.length; i++) { 
            if (i > 0) { 
                System.out.print(" "); 
            } 
            System.out.print(result[i]); 
        } 
        System.out.println(); 
    } 

    public static int[] minInterval(int[][] intervals, int[] queries) { 

        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0])); 

        int[][] sortedQueries = new int[queries.length][2]; 

        for (int i = 0; i < queries.length; i++) { 
            sortedQueries[i][0] = queries[i]; 
            sortedQueries[i][1] = i; 
        } 

        Arrays.sort(sortedQueries, (a, b) -> 
            Integer.compare(a[0], b[0]) 
        ); 

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> { 
            int sizeA = a[1] - a[0] + 1; 
            int sizeB = b[1] - b[0] + 1; 
            return Integer.compare(sizeA, sizeB); 
        }); 

        int[] result = new int[queries.length]; 
        Arrays.fill(result, -1); 

        int j = 0; 


        for (int[] query : sortedQueries) { 
            int q = query[0]; 
            int originalIndex = query[1]; 

            while (j < intervals.length && intervals[j][0] <= q) { 
                pq.offer(new int[] { 
                    intervals[j][0], intervals[j][1] 
                }); 
                j++; 
            } 

            while (!pq.isEmpty() && pq.peek()[1] < q) { 
                pq.poll(); 
            } 

            if (!pq.isEmpty()) { 
                int[] interval = pq.peek(); 
                result[originalIndex] = interval[1] - interval[0] + 1; 
            } 
        } 

        return result; 
    } 
}

