function solve(input) {
  const parts = input.trim().split(/\s+/);
  if (parts.length < 2) return "";
  const n = parseInt(parts[0], 10);
  const intervals = [];
  let idx = 1;
  for (let i = 0; i < n; i++) {
    intervals.push([parseInt(parts[idx], 10), parseInt(parts[idx+1], 10)]);
    idx += 2;
  }
  const qCount = parseInt(parts[idx], 10);
  const queries = parts.slice(idx + 1, idx + 1 + qCount).map((q, i) => [parseInt(q, 10), i]);
  intervals.sort((a, b) => a[0] - b[0]);
  queries.sort((a, b) => a[0] - b[0]);
  const res = Array(qCount).fill(-1);
  let itIdx = 0;
  const heap = [];
  for (const [qVal, origIdx] of queries) {
    while (itIdx < n && intervals[itIdx][0] <= qVal) {
      const [l, r] = intervals[itIdx];
      heap.push({ len: r - l + 1, end: r });
      itIdx++;
    }
    let minLen = -1;
    for (let i = heap.length - 1; i >= 0; i--) {
      if (heap[i].end < qVal) heap.splice(i, 1);
      else if (minLen === -1 || heap[i].len < minLen) minLen = heap[i].len;
    }
    res[origIdx] = minLen;
  }
  return res.join(' ');
}
